#include "maidionis/model.h"
#include <torch/torch.h>
#include <fstream>
#include <iostream>
#include <ctime>
using namespace maidionis;
Batch make_batch(const Json& rows){std::vector<int64_t>x,y;for(auto&r:rows){for(auto v:r.at("input"))x.push_back(v.get<int64_t>());y.push_back(r.at("label").get<int64_t>());}Batch b;b.inputs=torch::from_blob(x.data(),{int64_t(rows.size()),9},torch::kInt64).clone();b.targets=torch::from_blob(y.data(),{int64_t(rows.size())},torch::kInt64).clone();b.mask=b.inputs.ne(0);b.segments=torch::zeros_like(b.inputs);b.target_mask=torch::ones_like(b.targets,torch::kBool);return b;}
Json evaluate(ModelPtr m,const Json& rows){m->eval();torch::NoGradGuard guard;Json scores=Json::array();for(size_t i=0;i<rows.size();i+=32){Json part=Json::array();for(size_t j=i;j<std::min(rows.size(),i+32);j++)part.push_back(rows[j]);auto b=make_batch(part);auto logits=m->forward(b);auto logp=torch::log_softmax(logits,1);auto pred=logits.argmax(1);for(size_t j=0;j<part.size();j++)scores.push_back({{"family",part[j].at("family")},{"target_index",part[j].at("target_index")},{"target",b.targets[j].item<int64_t>()},{"prediction",pred[j].item<int64_t>()},{"nll",-logp[j][b.targets[j].item<int64_t>()].item<double>()}});}return scores;}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("DATA OUTPUT required");Json d;std::ifstream(argv[1])>>d;Json out={{"runs",Json::array()},{"environment",parse_json(numerical_environment())}};auto start=std::clock();for(auto&arm:d.at("arms")){auto seed=arm.at("seed").get<int64_t>();ModelConfig c;c.kind="encoder";c.hidden_width=256;c.input_width=2;c.output_width=49;c.vocabulary=51;c.controls={1};c.dropout_milli=0;auto m=make_seeded_model(c,seed);Json r={{"condition",arm.at("condition")},{"seed",seed},{"initial_test",evaluate(m,d.at("test"))}};torch::optim::AdamW opt(m->parameters(),torch::optim::AdamWOptions(0.0003).weight_decay(0));Json losses=Json::array();double delta=0;auto before=m->parameters()[0].detach().clone();for(auto&indices:arm.at("batches")){if(double(std::clock()-start)/CLOCKS_PER_SEC>300)throw std::runtime_error("CPU budget exceeded");Json rows=Json::array();for(auto index:indices)rows.push_back(arm.at("train")[index.get<size_t>()]);auto b=make_batch(rows);m->train();opt.zero_grad();auto loss=categorical_loss(m->forward(b),b.targets,b.target_mask);loss.backward();for(auto&p:m->parameters())if(!p.grad().defined()||!torch::isfinite(p.grad()).all().item<bool>())throw std::runtime_error("nonfinite gradient");torch::nn::utils::clip_grad_norm_(m->parameters(),1.);opt.step();m->enforce_constraints();losses.push_back(loss.item<double>());}delta=(m->parameters()[0]-before).abs().sum().item<double>();r["first_parameter_delta_l1"]=delta;r["losses"]=losses;r["final_test"]=evaluate(m,d.at("test"));r["final_train"]=evaluate(m,arm.at("train"));out["runs"].push_back(r);out["cpu_seconds"]=double(std::clock()-start)/CLOCKS_PER_SEC;std::ofstream(argv[2])<<out.dump(2)<<"\n";std::cerr<<arm.at("condition")<<" seed"<<seed<<" done cpu="<<out["cpu_seconds"]<<"\n";}return 0;}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
